  CurlGuard() = default;
  CurlGuard(const CurlGuard&) = delete;
  CurlGuard& operator=(const CurlGuard&) = delete;
  CurlGuard(CurlGuard&&) = delete;
  CurlGuard& operator=(CurlGuard&&) = delete;

  ~CurlGuard() {
    if (headers) {
