bool IsPrintableMenuInput(const fcitx::Key& key, bool filter_mode) {
  if (!filter_mode) {
    return false;
  }

  if (IsEnterKey(key) || IsEscapeKey(key) || IsSlashKey(key) || IsBackspaceKey(key) ||
      IsUpKey(key) || IsDownKey(key) || IsPagePrevKey(key) || IsPageNextKey(key) ||
